import { useQuery } from '@tanstack/react-query';
import { getJsonNow } from '../../api/http';

/** How figures are shown to a user: en (1234.56) or de (1.234,56). Entries are always typed with a dot. */
export type Locale = 'en' | 'de';

export const LOCALES: Locale[] = ['en', 'de'];

export type UserLocale = { user: string; locale: Locale };

// Kept per user, not per sheet: not under ['sheet', ...].
export const localeKey = (user: string) => ['user', user, 'locale'] as const;

export function localePath(user: string): string {
  return `/api/users/${encodeURIComponent(user)}/locale`;
}

/** The signed-in user's locale ('en' until it is read, or until they choose one). */
export function useLocale(user: string): Locale {
  const q = useQuery({
    queryKey: localeKey(user),
    queryFn: () => getJsonNow<UserLocale>(localePath(user)),
  });
  return q.data?.locale ?? 'en';
}

/** A figure: a number with two decimals, the whole of its text. */
const FIGURE = /^(-?)(\d+)\.(\d{2})$/;

/** The figure as shown under the locale; any other text unchanged. */
export function formatFigure(text: string, locale: Locale): string {
  if (locale !== 'de') return text;
  const m = FIGURE.exec(text.trim());
  if (!m) return text;
  return `${m[1]}${m[2].replace(/\B(?=(\d{3})+(?!\d))/g, '.')},${m[3]}`;
}
EOF
cat > features/locale/LocaleFigures.tsx <<'EOF'
import { useEffect, useRef } from 'react';
import type { ReactNode } from 'react';
import { formatFigure } from './locale';
import type { Locale } from './locale';

// Text inside these is never a figure shown in a cell (option labels are matched by tests and people as typed).
const SKIP = new Set(['OPTION', 'TEXTAREA', 'SCRIPT', 'STYLE']);

/** Shows every figure inside it in the user's locale: any element whose whole text is a number with two decimals
 *  (an amount, due, total, rate, share, cut...) is shown as 1.234,56 under de. Done on the screen's text, after
 *  React renders it, so each feature keeps rendering the plain figure it reads from the server (as exports and
 *  audit lines carry it); when the locale goes back to en every figure changed here is put back. */
export function LocaleFigures({ locale, children }: { locale: Locale; children: ReactNode }) {
  const ref = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const root = ref.current;
    if (!root || locale === 'en') return;
    // The text React rendered, for each text node shown differently here — to put back.
    const changed = new Map<Text, { plain: string; shown: string }>();

    const visit = (node: Text) => {
      const parent = node.parentElement;
      if (!parent || SKIP.has(parent.tagName)) return;
      const text = node.nodeValue ?? '';
      if ((parent.textContent ?? '').trim() !== text.trim()) return;
      const shown = formatFigure(text, locale);
      if (shown === text) return;
      changed.set(node, { plain: text, shown });
      node.nodeValue = shown;
    };
    const walk = (node: Node) => {
      if (node.nodeType === Node.TEXT_NODE) {
        visit(node as Text);
        return;
      }
      const texts = document.createTreeWalker(node, NodeFilter.SHOW_TEXT);
      for (let t = texts.nextNode(); t; t = texts.nextNode()) visit(t as Text);
    };

    walk(root);
    const observer = new MutationObserver((records) => {
      for (const r of records) {
        if (r.type === 'characterData') walk(r.target);
        else r.addedNodes.forEach(walk);
      }
    });
    observer.observe(root, { subtree: true, childList: true, characterData: true });
    return () => {
      observer.disconnect();
      for (const [node, { plain, shown }] of changed) {
        if (node.isConnected && node.nodeValue === shown) node.nodeValue = plain;
      }
    };
  }, [locale]);

  return (
    <div ref={ref} style={{ display: 'contents' }}>
      {children}
    </div>
  );
}
EOF
cat > features/locale/UserLocale.tsx <<'EOF'
import { useEffect, useState } from 'react';
import type { FormEvent } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { HttpError, putJson } from '../../api/http';
import { useSubmitOnce } from '../../api/useSubmitOnce';
import { LOCALES, localeKey, localePath, useLocale } from './locale';
import type { Locale, UserLocale as Saved } from './locale';

/** The signed-in user's locale: shown, and chosen with a select (saved per user; no audit line). */
export function UserLocale({ user }: { user: string }) {
  const queryClient = useQueryClient();
  const current = useLocale(user);
  const [chosen, setChosen] = useState<Locale>(current);
  const once = useSubmitOnce();

  useEffect(() => setChosen(current), [current]);

  const save = useMutation({
    mutationFn: (locale: Locale) => putJson<Saved>(localePath(user), { locale }),
    onSuccess: (saved) => queryClient.setQueryData(localeKey(user), saved),
    onSettled: once.done,
  });

  const submit = (e: FormEvent) => {
    e.preventDefault();
    save.reset();
    if (!once.start()) return;
    save.mutate(chosen);
  };

  return (
    <form data-testid="user-locale-form" onSubmit={submit}>
      Locale <strong data-testid="user-locale-current">{current}</strong>{' '}
      <label>
        Show figures as{' '}
        <select
          data-testid="user-locale"
          value={chosen}
          onChange={(e) => {
            setChosen(e.target.value as Locale);
            save.reset();
          }}
        >
          {LOCALES.map((l) => (
            <option key={l} value={l}>
              {l}
            </option>
          ))}
        </select>
      </label>{' '}
      <button type="submit" data-testid="user-locale-save" disabled={save.isPending}>
        Save locale
      </button>
      {save.isError && (
        <p data-testid="user-locale-error" role="alert">
          {save.error instanceof HttpError && save.error.body ? save.error.body : 'Could not change the locale.'}
        </p>
      )}
    </form>
  );
}
EOF
